@Component("goal-handler")
@ProcessingGroup("goal-processing-group")
public class GoalEventHandler {
	
	// core constructor
	GoalEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateGoalEvent
     */
    @EventHandler
    public void handle( CreateGoalEvent event) {
        entityManager.persist(new Goal(event.getGoalId(), event.getTitle(), event.getDescription(), event.getTargetDate(), event.getWeight(), event.getEmployee(), event.getCycle(), event.getParentGoal(), event.getChildGoals(), event.getStatus()));
    }

    /*
     * @param	event UpdateGoalEvent
     */
    @EventHandler
    public Goal handle( UpdateGoalEvent event) {
    	entityManager.merge(new Goal(event.getGoalId(), event.getTitle(), event.getDescription(), event.getTargetDate(), event.getWeight(), event.getEmployee(), event.getCycle(), event.getParentGoal(), event.getChildGoals(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteGoalEvent
     */
    @EventHandler
    public void on( DeleteGoalEvent event) {
    	Goal entity = new Goal();
   
    	// ------------------------------------------
    	// apply the GoalId
    	// ------------------------------------------
    	entity.setGoalId( event.getGoalId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final GoalRepository goalEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(GoalEventHandler.class.getName());

}
